"use client";

import { useEffect, useRef, type HTMLAttributes, type ReactNode } from "react";

export function Drawer({ open, onOpenChange, children, side = "bottom", className = "" }: { open: boolean; onOpenChange: (open: boolean) => void; children: ReactNode; side?: "bottom" | "left" | "right"; className?: string }) { const ref = useRef<HTMLDialogElement>(null); useEffect(() => { const node = ref.current; if (open && node && !node.open) node.showModal(); if (!open && node?.open) node.close(); }, [open]); const placement = side === "left" ? "co-me-auto co-h-full co-max-h-none co-w-[min(24rem,90vw)]" : side === "right" ? "co-ms-auto co-h-full co-max-h-none co-w-[min(24rem,90vw)]" : "co-mt-auto co-w-full co-max-w-none co-rounded-b-none"; return <dialog ref={ref} className={`${placement} co-rounded-xl co-border co-border-black/15 co-bg-white co-p-6 co-shadow-xl backdrop:co-bg-black/55 ${className}`.trim()} onCancel={() => onOpenChange(false)} onClose={() => onOpenChange(false)}>{children}</dialog>; }
export function DrawerHeader({ className = "", ...props }: HTMLAttributes<HTMLDivElement>) { return <div className={`co-grid co-gap-2 ${className}`.trim()} {...props} />; }
export function DrawerFooter({ className = "", ...props }: HTMLAttributes<HTMLDivElement>) { return <div className={`co-mt-6 co-flex co-justify-end co-gap-2 ${className}`.trim()} {...props} />; }
